<!DOCTYPE html>
<html class="dark" lang="id"><head><meta charset="utf-8"/><meta content="width=device-width, initial-scale=1.0" name="viewport"/><meta content="web_blank" name="shell-type"/><title>Masuk ke DracoRent — Sistem Rental Naga</title><link href="https://fonts.googleapis.com" rel="preconnect"/><link crossorigin="" href="https://fonts.gstatic.com" rel="preconnect"/><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&amp;family=Libre+Caslon+Text:ital,wght@0,400;0,700;1,400&amp;display=swap" rel="stylesheet"/><link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200" rel="stylesheet"/>
<link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap" rel="stylesheet"/><style>@layer base{html,body{margin:0;padding:0;}body{overscroll-behavior:none;}main>:first-child{margin-top:0!important;}main>:last-child{margin-bottom:0!important;}}::-webkit-scrollbar{display:none;}</style><script src="https://cdn.tailwindcss.com"></script><script id="tailwind-config">tailwind.config={darkMode:"class",theme:{extend:{"colors":{"tertiary-container":"#a3a6af","surface-raised":"#282C33","status-info":"#8FB5D1","on-tertiary":"#2d3138","secondary-fixed":"#dee2ed","on-tertiary-fixed":"#181c22","surface-container-lowest":"#0c0e12","on-secondary-fixed-variant":"#42474f","on-secondary":"#2c3138","surface":"#202329","tertiary-fixed":"#dfe2ec","on-surface-variant":"#d1c5b4","outline":"#9a8f80","surface-container":"#1e2024","on-secondary-fixed":"#171c23","on-primary":"#412d00","surface-dim":"#111317","text-subtle":"#898D93","on-primary-fixed":"#261900","secondary-container":"#444951","on-primary-container":"#4f3800","surface-container-high":"#282a2e","gold-ink":"#1A1916","status-danger-bg":"#412527","status-info-bg":"#242F39","status-borrowed":"#D5A35B","error":"#ffb4ab","on-primary-fixed-variant":"#5c4202","on-surface":"#e2e2e8","status-available":"#6EB895","text-muted":"#B0B2B5","text-primary":"#F0EBDD","secondary-fixed-dim":"#c2c7d0","gold-hover":"#D5B873","secondary":"#c2c7d0","primary-fixed":"#ffdea4","inverse-surface":"#e2e2e8","status-borrowed-bg":"#3C3020","surface-container-highest":"#333539","inverse-primary":"#775a1b","primary-container":"#c5a15b","primary-fixed-dim":"#e8c178","status-danger":"#E17B79","on-background":"#e2e2e8","status-available-bg":"#20392F","tertiary-fixed-dim":"#c3c6cf","on-tertiary-container":"#383c43","surface-variant":"#333539","surface-bright":"#37393e","tertiary":"#c3c6cf","on-tertiary-fixed-variant":"#43474e","primary":"#e8c178","inverse-on-surface":"#2f3035","surface-container-low":"#1a1c20","on-secondary-container":"#b4b8c2","on-error-container":"#ffdad6","surface-tint":"#e8c178","border":"#41464E","outline-variant":"#4e4639","error-container":"#93000a","on-error":"#690005","surface-muted":"#1C1F24","background":"#111317"},"borderRadius":{"DEFAULT":"0.125rem","lg":"0.25rem","xl":"0.5rem","full":"0.75rem"},"spacing":{"space-xs":"0.25rem","gutter-desktop":"1.5rem","gutter":"1rem","space-xl":"2.5rem","margin":"1rem","space-lg":"1.5rem","margin-tablet":"1.5rem","space-md":"1rem","margin-desktop":"2rem","space-sm":"0.5rem"},"fontFamily":{"label-regular":["Inter"],"hero-title-mobile":["Libre Caslon Text"],"helper-text":["Inter"],"card-title":["Libre Caslon Text"],"hero-title":["Libre Caslon Text"],"section-title":["Libre Caslon Text"],"page-title":["Libre Caslon Text"],"table-data":["Inter"],"body-default":["Inter"],"body-compact":["Inter"],"code-metadata":["Inter"]},"fontSize":{"label-regular":["13px",{"lineHeight":"18px","fontWeight":"500"}],"hero-title-mobile":["34px",{"lineHeight":"38px","fontWeight":"600"}],"helper-text":["12px",{"lineHeight":"16px","fontWeight":"400"}],"card-title":["18px",{"lineHeight":"24px","fontWeight":"600"}],"hero-title":["48px",{"lineHeight":"52px","letterSpacing":"-0.01em","fontWeight":"600"}],"section-title":["22px",{"lineHeight":"28px","fontWeight":"600"}],"page-title":["30px",{"lineHeight":"36px","fontWeight":"600"}],"table-data":["13px",{"lineHeight":"18px","fontWeight":"400"}],"body-default":["15px",{"lineHeight":"24px","fontWeight":"400"}],"body-compact":["14px",{"lineHeight":"20px","fontWeight":"400"}],"code-metadata":["11px",{"lineHeight":"16px","letterSpacing":"0.04em","fontWeight":"600"}]}}}};</script></head><body class="bg-background font-body-default text-text-primary antialiased min-h-screen"><main class="w-full min-h-screen flex flex-col justify-center"><div class="flex flex-col w-full py-8 md:py-12 px-4 sm:px-6 lg:px-8 max-w-[1360px] mx-auto my-auto">
<div class="grid grid-cols-1 lg:grid-cols-12 rounded-xl overflow-hidden bg-surface shadow-2xl border border-border">
<!-- LEFT PANEL: Atmospheric Dragon Registry Visuals & Archival Lore -->
<div class="relative lg:col-span-6 xl:col-span-7 flex flex-col justify-between p-8 sm:p-12 lg:p-16 min-h-[520px] lg:min-h-[720px] bg-surface-dim overflow-hidden">
<div class="absolute inset-0 bg-cover bg-center mix-blend-luminosity opacity-35" style="background-image: url('../images/dragons/red.jpg')"></div>
<div class="absolute inset-0 bg-gradient-to-t from-surface-dim via-surface-dim/80 to-transparent"></div>
<div class="absolute inset-0 bg-gradient-to-r from-surface-dim/90 via-surface-container/40 to-transparent"></div>
<!-- Top Guild Insignia & Registry Metadata -->
<div class="relative z-10 space-y-6">
<div class="inline-flex items-center gap-3 px-3.5 py-1.5 rounded-full bg-surface-muted/90 text-text-subtle border border-border">
<span class="w-2 h-2 rounded-full bg-status-available"></span>
<span class="font-code-metadata text-code-metadata uppercase tracking-wider text-text-muted">Protokol Keamanan Warkat • Bab 5.1</span>
</div>
<div class="max-w-md">
<p class="font-code-metadata text-code-metadata uppercase tracking-widest text-primary-container mb-2">Kaer Drakon • Wilayah Sayap Barat</p>
<h2 class="font-section-title text-section-title text-text-primary tracking-tight">Pustaka &amp; Pengawasan Inventaris Naga Kaer Drakon</h2>
<p class="mt-3 font-body-compact text-body-compact text-text-muted leading-relaxed">
            Pusat administrasi logistik armada naga taktis, pencatatan sertifikasi penunggang berlisensi, serta kendali warkat sewa-pakai terikat sumpah.
          </p>
</div>
</div>
<!-- Middle Decorative Element -->
<div class="relative z-10 my-8 py-6 px-6 rounded-lg bg-surface-container-low/80 backdrop-blur-sm border border-border">
<div class="flex items-start justify-between gap-4">
<div class="space-y-1">
<span class="font-code-metadata text-code-metadata text-primary-fixed-dim uppercase tracking-wider">Unit Siaga Terverifikasi</span>
<div class="font-card-title text-card-title text-text-primary">Ignis Ashbringer #NGA-101</div>
<p class="font-helper-text text-helper-text text-text-muted">Inspeksi teras kuartal: Bersih • Lisensi Penunggang: Tingkat II</p>
</div>
<span class="px-2.5 py-1 rounded bg-status-available-bg text-status-available font-code-metadata text-code-metadata font-semibold">SIAP DISPATCH</span>
</div>
</div>
<!-- Bottom Archival Seal -->
<div class="relative z-10 pt-6 space-y-3">
<div class="flex items-center gap-4 text-text-subtle font-helper-text text-helper-text">
<div class="flex items-center gap-1.5">
<span class="material-symbols-outlined text-[18px] text-primary">verified_user</span>
<span>Enkripsi Kriptografis Warkat</span>
</div>
<span class="text-secondary-container">•</span>
<div class="flex items-center gap-1.5">
<span class="material-symbols-outlined text-[18px] text-primary">shield</span>
<span>Ledger Bersegel Magis</span>
</div>
</div>
<p class="font-helper-text text-helper-text text-text-subtle">
          Segala manipulasi rekaman registri naga dikenai sanksi administratif kurator dan pencabutan wewenang penunggang secara permanen.
        </p>
</div>
</div>
<!-- RIGHT PANEL: Authentication Form -->
<div class="lg:col-span-6 xl:col-span-5 flex flex-col justify-center p-8 sm:p-12 lg:p-14 bg-surface">
<!-- Brand Lockup -->
<div class="flex items-center gap-3 mb-6">
<div class="w-10 h-10 rounded-lg bg-surface-muted border border-primary-container flex items-center justify-center text-primary shadow-sm">
<span class="material-symbols-outlined text-2xl" style="font-variation-settings: 'FILL' 1;">shield_with_house</span>
</div>
<div>
<div class="font-section-title text-section-title leading-tight tracking-tight text-text-primary flex items-center gap-2">
<span>DracoRent</span>
<span class="px-2 py-0.5 rounded text-[10px] font-code-metadata font-bold tracking-wider uppercase bg-surface-raised text-primary">Reg. v3.4</span>
</div>
<p class="font-helper-text text-helper-text text-text-subtle tracking-wide">Sistem Rental Naga • Kaer Drakon</p>
</div>
</div>
<!-- Header & Context Description -->
<div class="mb-6">
<h1 class="font-page-title text-page-title text-text-primary mb-2">Masuk ke DracoRent</h1>
<p class="font-body-compact text-body-compact text-text-muted">
          Akses warkat kontrak dan registri serikat untuk Kurator Admin dan Anggota Penunggang.
        </p>
</div>
<!-- Quick Select Demo Accounts Box -->
<div class="mb-6 p-3.5 rounded-lg bg-surface-muted border border-primary-container/50 space-y-2.5">
<div class="font-code-metadata text-code-metadata text-primary uppercase tracking-wider flex items-center justify-between">
<span>⚡ Pilih Akun Cepat (Klik untuk Isi Otomatis)</span>
<span class="text-status-available font-bold">SANDI: 123456</span>
</div>
<div class="grid grid-cols-2 gap-2.5">
<button class="px-3 py-2 rounded bg-surface border border-border hover:border-primary text-left hover:bg-surface-raised transition-all group" onclick="fillDemoAccount('admin@dracorent.com', '123456')" type="button">
<div class="font-code-metadata text-[10px] text-primary uppercase font-bold">1. Login Admin</div>
<div class="font-code-metadata text-[12px] text-text-primary truncate mt-0.5">admin@dracorent.com</div>
<div class="font-helper-text text-[11px] text-text-subtle">Sandi: <strong class="text-text-primary">123456</strong></div>
</button>
<button class="px-3 py-2 rounded bg-surface border border-border hover:border-primary text-left hover:bg-surface-raised transition-all group" onclick="fillDemoAccount('user@dracorent.com', '123456')" type="button">
<div class="font-code-metadata text-[10px] text-status-available uppercase font-bold">2. Login Anggota</div>
<div class="font-code-metadata text-[12px] text-text-primary truncate mt-0.5">user@dracorent.com</div>
<div class="font-helper-text text-[11px] text-text-subtle">Sandi: <strong class="text-text-primary">123456</strong></div>
</button>
</div>
</div>
<!-- Main Form -->
<form class="space-y-5" id="dracoLoginForm" onsubmit="event.preventDefault(); handleAuthSubmit();">
<!-- Field 1: Email / Username -->
<div class="space-y-2">
<div class="flex justify-between items-center">
<label class="font-label-regular text-label-regular text-text-primary flex items-center gap-1" for="guildEmail">
              Email / Username
              <span class="text-primary">*</span>
</label>
<span class="font-code-metadata text-code-metadata text-text-subtle">Ketik: admin atau user</span>
</div>
<div class="relative">
<div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-text-subtle">
<span class="material-symbols-outlined text-[19px]">mail</span>
</div>
<input class="w-full bg-surface-muted border border-border text-text-primary placeholder:text-text-subtle font-body-compact text-body-compact rounded px-3.5 py-2.5 pl-10 focus:outline-none focus:ring-1 focus:ring-primary transition-colors" id="guildEmail" name="guildEmail" placeholder="admin@dracorent.com atau user@dracorent.com" required="" type="text" value="admin@dracorent.com"/>
</div>
</div>
<!-- Field 2: Password with Reveal Toggle -->
<div class="space-y-2">
<div class="flex justify-between items-center">
<label class="font-label-regular text-label-regular text-text-primary flex items-center gap-1" for="guildPassword">
              Kata Sandi Masuk
              <span class="text-primary">*</span>
</label>
<span class="font-helper-text text-helper-text text-text-subtle">Default: 123456</span>
</div>
<div class="relative">
<div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-text-subtle">
<span class="material-symbols-outlined text-[19px]">lock</span>
</div>
<input class="w-full bg-surface-muted border border-border text-text-primary placeholder:text-text-subtle font-body-compact text-body-compact rounded px-3.5 py-2.5 pl-10 pr-10 focus:outline-none focus:ring-1 focus:ring-primary transition-colors" id="guildPassword" name="guildPassword" placeholder="Masukkan sandi (123456)" required="" type="password" value="123456"/>
<button aria-label="Tampilkan atau sembunyikan kata sandi" class="absolute inset-y-0 right-0 pr-3.5 flex items-center text-text-subtle hover:text-text-primary focus:outline-none transition-colors" id="togglePasswordBtn" onclick="togglePasswordVisibility()" type="button">
<span class="material-symbols-outlined text-[19px]" id="passwordIcon">visibility</span>
</button>
</div>
</div>
<!-- Checkbox: Remember Session -->
<div class="flex items-center justify-between pt-1">
<label class="flex items-center gap-2.5 cursor-pointer select-none">
<input checked="" class="w-4 h-4 rounded bg-surface-muted text-primary focus:ring-0 focus:ring-offset-0 cursor-pointer accent-[#C5A15B]" id="rememberSession" type="checkbox"/>
<span class="font-helper-text text-helper-text text-text-muted hover:text-text-primary transition-colors">Ingat sesi perangkat pos ini</span>
</label>
<span class="font-code-metadata text-code-metadata text-text-subtle">BR-01 AUTH</span>
</div>
<!-- Primary Action Button: Guild Gold -->
<div class="pt-2">
<button class="w-full min-h-[44px] flex items-center justify-center gap-2 rounded bg-primary-container text-gold-ink font-semibold font-label-regular text-label-regular hover:bg-gold-hover active:bg-[#B28F47] focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-surface transition-all shadow-md cursor-pointer" id="submitAuthBtn" type="submit">
<span class="material-symbols-outlined text-[20px]" style="font-variation-settings: 'FILL' 1;">login</span>
<span>Buka Warkat &amp; Masuk</span>
</button>
</div>
</form>
<!-- Feedback Area -->
<div class="hidden mt-4 p-3 rounded-lg bg-surface-raised border border-status-available/40 font-helper-text text-helper-text" id="loginFeedback"></div>
</div>
</div>
</div>
<script>
  function togglePasswordVisibility() {
    const passwordInput = document.getElementById('guildPassword');
    const passwordIcon = document.getElementById('passwordIcon');
    if (!passwordInput || !passwordIcon) return;

    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      passwordIcon.textContent = 'visibility_off';
    } else {
      passwordInput.type = 'password';
      passwordIcon.textContent = 'visibility';
    }
  }

  function fillDemoAccount(email, pass) {
    const emailField = document.getElementById('guildEmail');
    const passField = document.getElementById('guildPassword');
    if (emailField && passField) {
      emailField.value = email;
      passField.value = pass;
      emailField.focus();
    }
  }

  function handleAuthSubmit() {
    const email = (document.getElementById('guildEmail').value || '').trim().toLowerCase();
    const btn = document.getElementById('submitAuthBtn');
    const feedback = document.getElementById('loginFeedback');
    if (!btn || !feedback) return;

    const isAdmin = email.includes('admin') || email.includes('kurator') || email.includes('kaelen');
    const targetSlug = isAdmin ? 'ringkasan' : 'katalog-naga';

    btn.disabled = true;
    btn.innerHTML = `<span class="material-symbols-outlined text-[19px] animate-spin">refresh</span><span>Memverifikasi Warkat...</span>`;

    feedback.classList.remove('hidden');
    feedback.innerHTML = `
      <div class="flex items-center gap-2 text-status-available">
        <span class="material-symbols-outlined text-[18px]">verified</span>
        <span class="font-semibold">Login Berhasil:</span>
        <span>Masuk sebagai ${isAdmin ? 'Admin Kurator' : 'Anggota Serikat'}. Mengalihkan...</span>
      </div>
    `;

    setTimeout(() => {
      if (window.parent && window.parent !== window && window.parent.switchDracoScreen) {
        window.parent.switchDracoScreen(targetSlug);
      } else {
        const inScreensDir = window.location.pathname.replace(/\\/g, '/').includes('/screens/');
        window.location.href = inScreensDir ? (targetSlug + '.html') : ('screens/' + targetSlug + '.html');
      }
    }, 500);
  }
</script></main><script src="/js/dracorent-app.js"></script></body></html>
